// Exportación privada. Nunca imprime SQL, claves, contactos ni URLs firmadas.
import {mkdir,writeFile,readFile} from 'node:fs/promises';
import {createHash,randomBytes,createCipheriv,publicEncrypt,constants} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const account=process.env.CLOUDFLARE_ACCOUNT_ID,token=process.env.CLOUDFLARE_API_TOKEN;
const output='/tmp/octavia-security',repository=process.env.GITHUB_REPOSITORY;
if(!account||!token||!process.env.BACKUP_PUBLIC_KEY)throw Error('Falta la configuración segura de copia.');
await mkdir(output+'/datos',{recursive:true});
async function cf(path,method='GET',body){const response=await fetch('https://api.cloudflare.com/client/v4/accounts/'+account+path,{method,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok||!data.success)throw Error('Cloudflare no permitió completar la copia (HTTP '+response.status+').');return data.result;}
const databases=await cf('/d1/database?name=octavia-club-mercadillo&per_page=100'),database=databases.find(db=>db.name==='octavia-club-mercadillo');if(!database)throw Error('No se encuentra la base de datos de producción.');
let result=await cf('/d1/database/'+database.uuid+'/export','POST',{output_format:'polling'});
for(let i=0;result.status!=='complete'&&i<120;i++){if(result.status==='error'||result.error)throw Error('No se pudo exportar la base de datos.');await new Promise(resolve=>setTimeout(resolve,1000));result=await cf('/d1/database/'+database.uuid+'/export','POST',{output_format:'polling',current_bookmark:result.at_bookmark});}
if(result.status!=='complete'||!result.result?.signed_url)throw Error('La exportación no terminó dentro del plazo.');
const sqlResponse=await fetch(result.result.signed_url,{signal:AbortSignal.timeout(120000)});if(!sqlResponse.ok)throw Error('No se pudo recuperar la instantánea SQL.');await writeFile(output+'/datos/produccion.sql',new Uint8Array(await sqlResponse.arrayBuffer()));
const project=await cf('/pages/projects/octaviaap'),production=project.deployment_configs?.production||{};
const config={name:'archivo de seguridad OCTAVIA WEB',createdAt:new Date().toISOString(),createdAtMadrid:new Date().toLocaleString('es-ES',{timeZone:'Europe/Madrid'}),sourceCommit:process.env.GITHUB_SHA,repository,site:'https://octaviaap.pages.dev',cloudflare:{accountId:account,project:project.name,subdomain:project.subdomain,branch:project.production_branch||'main',database:{name:database.name,id:database.uuid,binding:'MARKET_DB'},compatibilityDate:production.compatibility_date,compatibilityFlags:production.compatibility_flags||[],runtimeVariableNames:Object.keys(production.env_vars||{})},secrets:{exported:false,existingGithubSecret:'CLOUDFLARE_API_TOKEN',requiredPermissions:['Account / Cloudflare Pages / Edit','Account / D1 / Edit'],note:'Los secretos de servicio no se exportan. La recuperación usa la conexión y el secreto existentes, o una sesión autorizada equivalente.'},databaseExport:{complete:true,bookmark:result.at_bookmark},features:['Cabecera ŠKODA y bandera animada','Fondos de humo','Garaje con carpetas, piloto, Instagram, WhatsApp y avatar','Galería decorativa y álbumes de eventos','Calendario y enlace de Google Maps','Mercadillo moderado y borrado de vendidos a las 24 horas','Campana de notificaciones y sonido de cierre centralizado','Reglamento completo de carretera','Simulador 3D WebGL 2 / Three.js / PBR / HDR, tres niveles y alternativa 2D','Radio con MP3 del club'],email:{implemented:true,active:!!production.env_vars?.RESEND_API_KEY,recipient:'mozos.raul@gmail.com',note:'Sin RESEND_API_KEY no se envían correos; se conserva la revisión en la web.'}};
await writeFile(output+'/configuracion.json',JSON.stringify(config,null,2));
execFileSync('python',['.github/backup/empaquetar.py',output],{stdio:'inherit'});
const zip=await readFile(output+'/archivo de seguridad OCTAVIA WEB.zip'),key=randomBytes(32),iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',key,iv);const encrypted=Buffer.concat([cipher.update(zip),cipher.final()]);
const envelope={format:'OCTAVIA-BACKUP-AES256GCM-RSAOAEP-SHA256-V2',iv:iv.toString('base64'),tag:cipher.getAuthTag().toString('base64'),wrappedKey:publicEncrypt({key:process.env.BACKUP_PUBLIC_KEY,oaepHash:'sha256',padding:constants.RSA_PKCS1_OAEP_PADDING},key).toString('base64'),sha256:createHash('sha256').update(zip).digest('hex'),ciphertextSha256:createHash('sha256').update(encrypted).digest('hex'),zipBytes:zip.length,ciphertextBytes:encrypted.length,sourceCommit:process.env.GITHUB_SHA,repository};
const delivery=output+'/entrega';await mkdir(delivery,{recursive:true});await writeFile(delivery+'/archivo-seguridad-octavia-web.cifrado.bin',encrypted);await writeFile(delivery+'/manifest.json',JSON.stringify(envelope,null,2));
console.log('COPIA_CIFRADA_OK '+JSON.stringify({artifact:'copia-seguridad-octavia-web-'+process.env.GITHUB_RUN_ID,bytes:envelope.zipBytes,ciphertextBytes:envelope.ciphertextBytes,sha256:envelope.sha256,ciphertextSha256:envelope.ciphertextSha256}));
